# ----------------------------------------------------------- structural facts
def check_shape_is_transposed(solve):
    for (nk, nm) in [(4, 8), (6, 13), (5, 5), (1, 8), (8, 1)]:
        for norm in (None, "ortho"):
            m = C(solve, "matrix", n_mfcc=nk, n_mels=nm, norm=norm)
            assert isinstance(m, list), "matrix must be a list"
            assert len(m) == nm, "rows must equal n_mels (%d), got %d" % (nm, len(m))
            assert len(m[0]) == nk, "cols must equal n_mfcc (%d), got %d" % (nk, len(m[0]))


def check_corner_all_twos(solve):
    # (n=0,k=0) -> cos(0)=1 -> *2 = 2 for norm=None, every size
    for (nk, nm) in [(4, 8), (13, 6), (5, 5), (16, 9), (32, 32), (1, 1), (1, 8), (8, 1)]:
        m = C(solve, "matrix", n_mfcc=nk, n_mels=nm, norm=None)
        _near(m[0][0], 2.0, "corner[0][0] %dx%d" % (nm, nk))


def check_transpose_formula(solve):
    # returned[i][j] = 2*cos(pi/n_mels*(i+0.5)*j) for norm=None
    nm, nk = 13, 6
    m = C(solve, "matrix", n_mfcc=nk, n_mels=nm, norm=None)
    for i in range(nm):
        for j in range(nk):
            want = 2.0 * math.cos(math.pi / nm * (i + 0.5) * j)
            _near(m[i][j], want, "transpose %dx%d[%d,%d]" % (nm, nk, i, j))


def check_ortho_first_column(solve):
    # built dct[0] scaled -> after transpose, returned COLUMN 0 carries 1/sqrt2
    nm, nk = 13, 6
    m = C(solve, "matrix", n_mfcc=nk, n_mels=nm, norm="ortho")
    none = C(solve, "matrix", n_mfcc=nk, n_mels=nm, norm=None)
    for i in range(nm):
        want = (none[i][0] / 2.0) * (1.0 / math.sqrt(2.0)) * math.sqrt(2.0 / nm)
        _near(m[i][0], want, "ortho col0 %dx%d[%d]" % (nm, nk, i))


def check_ortho_full_scale(solve):
    nm, nk = 16, 9
    m = C(solve, "matrix", n_mfcc=nk, n_mels=nm, norm="ortho")
    for i in range(nm):
        for j in range(nk):
            want = math.cos(math.pi / nm * (i + 0.5) * j) * \
                   (1.0 / math.sqrt(2.0) if j == 0 else 1.0) * math.sqrt(2.0 / nm)
            _near(m[i][j], want, "ortho scale %dx%d[%d,%d]" % (nm, nk, i, j))


def check_ortho_orthonormality(solve):
    # square ortho matrix is orthonormal: D @ D.T == I
    for nm in (1, 2, 3, 4, 5, 8, 12, 16, 32):
        m = C(solve, "matrix", n_mfcc=nm, n_mels=nm, norm="ortho")
        prod = _matmul(m, _transpose(m))
        for i in range(nm):
            for j in range(nm):
                want = 1.0 if i == j else 0.0
                _near(prod[i][j], want, "D@D.T %dx%d[%d,%d]" % (nm, nm, i, j), rtol=1e-7, atol=1e-7)


def check_matrix_nonnegative_unused(solve):
    # sanity: all entries finite
    m = C(solve, "matrix", n_mfcc=9, n_mels=16, norm=None)
    for v in _leaves(m):
        assert isinstance(v, float), "matrix leaves must be floats"


# ----------------------------------------------------------- norm validation
def check_norm_error_bogus(solve):
    r = C(solve, "norm_error", norm="bogus")
    assert isinstance(r, dict) and r["type"] == "ValueError", "bogus must ValueError"
    assert r["msg"] == 'norm must be either "ortho" or None', "exact msg: %r" % r.get("msg")


def check_norm_error_case_sensitive(solve):
    for bad in ("ORTHO", "orthogonal", "", "none", "None"):
        r = C(solve, "norm_error", norm=bad)
        assert isinstance(r, dict) and r["type"] == "ValueError", "%r must ValueError" % bad
        assert r["msg"] == 'norm must be either "ortho" or None', "%r msg: %r" % (bad, r.get("msg"))


def check_norm_error_valid(solve):
    assert C(solve, "norm_error", norm=None) == "NO_ERROR"
    assert C(solve, "norm_error", norm="ortho") == "NO_ERROR"


def check_matrix_invalid_norm_error(solve):
    # matrix mode must also surface the ValueError as an error dict
    r = C(solve, "matrix", n_mfcc=4, n_mels=8, norm="bogus")
    assert isinstance(r, dict) and r["type"] == "ValueError", "matrix bogus -> err dict"
    assert r["msg"] == 'norm must be either "ortho" or None', "matrix msg: %r" % r.get("msg")


# ----------------------------------------------------------- census
def check_census(solve):
    c = C(solve, "census")
    assert c == CENSUS, "census mismatch: %r" % c


# ----------------------------------------------------------- edge sizes
def check_edge_n_mels_zero(solve):
    # n_mels=0 -> division by zero; official raises ZeroDivisionError
    r = C(solve, "matrix", n_mfcc=4, n_mels=0, norm=None)
    assert isinstance(r, dict) and r["type"] == "ZeroDivisionError", "n_mels=0 degenerate"


def check_edge_n_mfcc_zero(solve):
    # n_mfcc=0 -> shape (n_mels, 0): 0 columns, no error
    r = C(solve, "matrix", n_mfcc=0, n_mels=8, norm=None)
    assert isinstance(r, list) and (len(r) == 0 or len(r[0]) == 0), "n_mfcc=0 -> 0 cols"


def check_unknown_mode(solve):
    try:
        C(solve, "bogus_mode_867")
    except ValueError as e:
        msg = str(e)
        assert "unknown mode" in msg, "message must say 'unknown mode': %r" % msg
        assert "expected one of" in msg, "message must list modes: %r" % msg
        assert "bogus_mode_867" in msg, "message must echo the mode: %r" % msg
        # the real mode list (not the literal word "MODES") must be present
        assert "matrix" in msg and "census" in msg, "mode list missing: %r" % msg
    else:
        raise AssertionError("no error raised for unknown mode")
